import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ClassUtils.toClass(Object[] array)
 */
public class ClassUtils_toClass_TriageGen2Test {







    @Test
    public void testToClass_WithNullElements() {
        Object[] input = new Object[]{"String", null, 123};
        Class<?>[] result = ClassUtils.toClass(input);

        Assert.assertNotNull(result);
        Assert.assertEquals(3, result.length);
        Assert.assertEquals(String.class, result[0]);
        Assert.assertNull("Null element in input should result in null in output array", result[1]);
        Assert.assertEquals(Integer.class, result[2]);
    }


}

